cess": {"is_oa": true, "oa_status": "gold", "oa_url": "https://www.mdpi.com/1099-4300/21/8/763/pdf?version=1565173982", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.3390/e21080763", "doi": "https://doi.org/10.3390/e21080763", "is_oa": true, "landing_page_url": "https://doi.org/10.3390/e21080763", "pdf_url": "https://www.mdpi.com/1099-4300/21/8/763/pdf?version=1565173982", "source": {"id": "https://openalex.org/S195231649", "display_name": "Entropy", "issn_l": "1099-4300", "issn": ["1099-4300"], "is_oa": true, "is_in_doaj": true, "is_core": true, "listed_in": ["anvur-class-a", "anvur-scientific", "cwts-core", "doaj", "norway-1", "poland-100", "russia-white-list-2", "vabb-shw"], "host_organization": "https://openalex.org/P4310310987", "host_organization_name": "Multidisciplinary Digital Publishing Institute", "host_organization_lineage": ["https://openalex.org/P4310310987"], "host_organization_lineage_names": ["Multidisciplinary Digital Publishing Institute"], "type": "journal"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Entropy", "raw_type": "journal-article"}, "abstract": "Pattern classification represents a challenging problem in machine learning and data science research domains, especially when there is a limited availability of training samples. In recent years, artificial neural network (ANN) algorithms have demonstrated astonishing performance when compared to traditional generative and discriminative classification algorithms. However, due to the complexity of classical ANN architectures, ANNs are sometimes incapable of providing efficient solutions when addressing complex distribution problems. Motivated by the mathematical definition of a quantum bit (qubit), we propose a novel autonomous perceptron model (APM) that can solve the problem of the architecture complexity of traditional ANNs. APM is a nonlinear classification model that has a simple and fixed architecture inspired by the computational superposition power of the qubit. The proposed perceptron is able to construct the activation operators autonomously after a limited number of iterations. Several experiments using various datasets are conducted, where all the empirical results show the superiority of the proposed model as a classifier in terms of accuracy and computational time when it is compared with baseline classification models."}]", "excerpt_truncated": true, "source_sha256": "35024ea160d0bdf3e6ee7612f82c5199ea3a6d66bc842756d4c8750b72c823c3", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.48550/arxiv.2304.05332", "doi:10.1039/d1mh00495f", "doi:10.3390/e21080763", "openalex:W4365211632", "openalex:W3159986971", "arxiv:2304.05332"], "source_candidates": ["https://doi.org/10.48550/arxiv.2304.05332", "https://arxiv.org/pdf/2304.05332", "https://doi.org/10.1039/d1mh00495f", "https://pubs.rsc.org/en/content/articlepdf/2021/mh/d1mh00495f", "https://doi.org/10.3390/e21080763"], "source_candidate_identities": {}}

