ue, "is_published": true, "raw_source_name": "Journal of Artificial Intelligence for Materials Science", "raw_type": "journal-article"}, "abstract": null}, {"id": "https://openalex.org/W4382680334", "doi": "https://doi.org/10.1145/3605782", "title": "Curiosity Creates Diversity in Policy Search", "publication_year": 2023, "type": "article", "cited_by_count": 2, "open_access": {"is_oa": true, "oa_status": "bronze", "oa_url": "https://dl.acm.org/doi/pdf/10.1145/3605782", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1145/3605782", "doi": "https://doi.org/10.1145/3605782", "is_oa": true, "landing_page_url": "https://doi.org/10.1145/3605782", "pdf_url": "https://dl.acm.org/doi/pdf/10.1145/3605782", "source": {"id": "https://openalex.org/S4210221532", "display_name": "ACM Transactions on Evolutionary Learning and Optimization", "issn_l": "2688-299X", "issn": ["2688-299X", "2688-3007"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["ccf-c", "cwts-core", "jufo-1"], "host_organization": "https://openalex.org/P4310319798", "host_organization_name": "Association for Computing Machinery", "host_organization_lineage": ["https://openalex.org/P4310319798"], "host_organization_lineage_names": ["Association for Computing Machinery"], "type": "journal"}, "license": null, "license_id": null, "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "ACM Transactions on Evolutionary Learning and Optimization", "raw_type": "journal-article"}, "abstract": "When searching for policies, reward-sparse environments often lack sufficient information about which behaviors to improve upon or avoid. In such environments, the policy search process is bound to blindly search for reward-yielding transitions and no early reward can bias this search in one direction or another. A way to overcome this is to use intrinsic motivation in order to explore new transitions until a reward is found. In this work, we use a recently proposed definition of intrinsic motivation, Curiosity, in an evolutionary policy search method. We propose Curiosity-ES, 1 an evolutionary strategy adapted to use Curiosity as a fitness metric. We compare Curiosity-ES with other evolutionary algorithms intended for exploration, as well as with Curiosity-based reinforcement learning, and find that Curiosity-ES can generate higher diversity without the need for an explicit diversity criterion and leads to more policies which find reward."}]", "excerpt_truncated": true, "source_sha256": "6bc0ad29a017047cb78bfe33e772f31bdd480b7ec3e6c194fcc319253e64975c", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1145/3605782", "openalex:W7213482341", "openalex:W4382680334"], "source_candidates": ["https://doi.org/10.1145/3605782", "https://dl.acm.org/doi/pdf/10.1145/3605782"], "source_candidate_identities": {}}

